DO $$
BEGIN
  IF current_setting('apexprep.allow_dev_seed', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'dev seed refused: run it through `npm run db:seed` (NODE_ENV must not be production)';
  END IF;
END $$;

